# qx2_reverse_bits :: 0
def qx2_reverse_bits(n):
    out = 0
    for _ in range(32):
        out = (out << 1) | (n & 1)
        n >>= 1
    return out

if __name__ == '__main__':
    print(qx2_reverse_bits(0))

